<script setup lang="ts">
import {ref,onMounted} from 'vue';import {pmsApi} from './api';
const rows=ref<any[]>([]),total=ref(0),page=ref(1),busy=ref(false),error=ref('');
async function load(next=1){busy.value=true;error.value='';try{const result=await pmsApi('dashboard/deadlines?page='+next);rows.value=result.data;total.value=result.total;page.value=result.page;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(()=>void load());
</script>
<template><section><div class="admin-section-heading"><div><h2>Upcoming deadlines</h2><p class="muted">Open tasks due in the next seven days.</p></div><a class="button" href="/pms?section=dashboard">Back to dashboard</a></div><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><div class="pms-table-card"><div class="pms-table-scroll"><table class="pms-table"><thead><tr><th>Task</th><th>Project</th><th>Due date</th><th>Assignees</th></tr></thead><tbody><tr v-for="task in rows" :key="task.id"><td><a :href="'/pms?section=project-board&project='+task.project_id+'&issue='+task.id">{{task.title}}</a></td><td>{{task.project}}</td><td>{{new Date(task.due_date).toLocaleDateString()}}</td><td>{{task.assignees.map((a:any)=>a.name).join(', ')||'Unassigned'}}</td></tr><tr v-if="!rows.length&&!busy"><td colspan="4">No upcoming deadlines.</td></tr></tbody></table></div><div class="pms-datatable-footer"><span>{{total?((page-1)*20+1):0}}&ndash;{{Math.min(page*20,total)}} of {{total}} deadlines</span><div class="pms-pagination"><button :disabled="busy||page===1" @click="load(page-1)">Previous</button><button :disabled="busy||page*20>=total" @click="load(page+1)">Next</button></div></div></div></section></template>
